#!/usr/bin/env bun

import { readFileSync } from "node:fs"
import { join } from "node:path"

const dir = import.meta.dir
const tokens: Record<string, string> = JSON.parse(readFileSync(join(dir, "tokens.json"), "utf8"))

const variables = Object.keys(tokens).map((name) => `--color-${name}: var(--${name});`)

const output = `
/* Generated by script/tailwind.ts */
/* Do not edit this file manually */

@theme {
  --color-*: initial;
  ${variables.join("\n  ")}
}
`

await Bun.file(join(dir, "..", "src", "styles", "tailwind", "colors.css")).write(output.trim())
